import itertools

# vertices 1..5
vertices = [1,2,3,4,5]
edges = []
edge_index = {}
idx = 0
for i in range(1,6):
    for j in range(i+1,6):
        edges.append((i,j))
        edge_index[(i,j)] = idx
        idx += 1

print("Edges:", edges)

# fixed assignments: c[3]=1, c[9]=0
fixed = {3:1, 9:0}

def check(coloring):
    # coloring is list of 10 ints
    for triple in itertools.combinations(vertices, 3):
        # edges among triple
        e = []
        for a,b in itertools.combinations(triple, 2):
            e.append(coloring[edge_index[(a,b)]])
        if all(x==0 for x in e) or all(x==1 for x in e):
            return False
    return True

solutions = []
for mask in range(1<<8):
    coloring = [None]*10
    # assign fixed
    for k,v in fixed.items():
        coloring[k] = v
    # assign others
    free_indices = [i for i in range(10) if i not in fixed]
    for pos, idx_free in enumerate(free_indices):
        bit = (mask >> pos) & 1
        coloring[idx_free] = bit
    if check(coloring):
        solutions.append(coloring[:])

print("Number of solutions:", len(solutions))
if solutions:
    print("First solution:", solutions[0])

sol = [0, 0, 1, 1, 1, 0, 1, 1, 0, 0]
print("Fixed check:", sol[3]==1, sol[9]==0)

def verify(coloring):
    for triple in itertools.combinations(vertices, 3):
        e = []
        for a,b in itertools.combinations(triple, 2):
            e.append(coloring[edge_index[(a,b)]])
        print(f"Triple {triple}: edges {e}, all same? {all(x==0 for x in e) or all(x==1 for x in e)}")
        if all(x==0 for x in e) or all(x==1 for x in e):
            return False
    return True

print("Valid?", verify(sol))

